        end

        function conf:compute_succ_configs(new_word, base_stack, input, stack_top, result)
            local next_transitions = pda:get_to_transitions(state, input, stack_top)
            for next_transition, _ in pairs(next_transitions) do
                local new_stack = base_stack:clone()
                if next_transition.label.push ~= "" and
                        not automata.is_empty_token_sequence(next_transition.label.push) then
                    if type(next_transition.label.push) == "string" then
                        new_stack:insert_left_modify(next_transition.label.push)
                    elseif automata.is_token_sequence(next_transition.label.push) then
                        for i=next_transition.label.push:len(),1,-1 do
                            new_stack:insert_left_modify(next_transition.label.push:get_char(i))
