        if purpose == "acceptance" then
            function conf:step()
                local word, stack = self:get_word(), self:get_stack()
                local new_word, input
                if word:len() > 0 then
                    new_word, input = word:pop_left_copy()
                end
                local popped_stack, stack_top
                if stack:len() > 0 then
                    popped_stack, stack_top = stack:pop_left_copy()
                end
                local result = {}
                if word:len() > 0 then
                    if stack:len() > 0 then
                        self:compute_succ_configs(new_word, popped_stack, input, stack_top, result)
                    end
                    self:compute_succ_configs(new_word, stack, input, "", result)
                end
                if stack:len() > 0 then
                    self:compute_succ_configs(word, popped_stack, "", stack_top, result)
                end
                self:compute_succ_configs(word, stack, "", "", result)
