                            and self:get_automaton():is_accepting(
                                self:get_state())
                elseif mode == "e" then
                    return self:get_stack():len() == 0
                            and self.steps > 0
                end
                return self:get_stack():len() == 0
                        and toboolean(self:get_state())
                        and self:get_automaton():is_accepting(
                            self:get_state())
            end
        elseif purpose == "generation" then
            function conf:is_accepting()
                local mode = accept_mode()
                if mode == "f" then
