                            and self:get_automaton():is_accepting(
                                self:get_state())
                elseif mode == "e" then
                    return self:get_stack():len() == 0
                            and self.steps > 0
                end
                return self:get_stack():len() == 0
                        and toboolean(self:get_state())
                        and self:get_automaton():is_accepting(
                            self:get_state())
            end
        end

        return conf
    end

    function automata.make_initial_pda_conf(pda, word, purpose)
        assert(automata.is_finished_pda(pda))
        assert(automata.is_token_sequence(word))
        local map = {}
        for k, _ in pairs(pda:get_stack_symbols()) do
            map[k] = k
        end
        return automata.make_pda_conf(pda, pda:get_initial(), word, automata.make_token_sequence(map), purpose)
    end

    automata.set_word_problem_entry({
        type="pda",
        nondeterministic=true,
        make_initial_conf=automata.make_initial_pda_conf})
end
